import openpyxl, re
path='/root/copy_of_capacity_sheet.xlsx'
wb=openpyxl.load_workbook(path, data_only=True)
print('sheets:', wb.sheetnames)
ws=wb['Weld']

# Find the row where first non-empty cell matches 'MIG weld Demand Total'
target='mig weld demand total'
match_row=None
match_cell=None
for row in ws.iter_rows(values_only=False):
    # find first non-empty cell in row
    first=None
    for cell in row:
        v=cell.value
        if v is None: 
            continue
        if isinstance(v,str) and v.strip()=='' :
            continue
        first=cell
        break
    if first is None:
        continue
    v=first.value
    if isinstance(v,str) and v.strip().lower()==target:
        match_row=first.row
        match_cell=first
        break

print('match_row:', match_row, 'match_cell:', match_cell.coordinate if match_cell else None)
if match_row is None:
    raise SystemExit('Target row not found')

# Inspect header rows above to find week columns.
# Heuristic: look for a row that contains many week numbers 1..60 or strings like 'Week 4'
header_candidate_rows=list(range(max(1,match_row-10), match_row))

def parse_week(val):
    if val is None:
        return None
    if isinstance(val,(int,float)):
        # treat integer-like
        if abs(val-round(val))<1e-9:
            w=int(round(val))
            if 1<=w<=100:
                return w
    if isinstance(val,str):
        s=val.strip().lower()
        # patterns
        m=re.search(r'week\s*(\d+)', s)
        if m:
            return int(m.group(1))
        # 'w4'
        m=re.fullmatch(r'w\s*(\d+)', s)
        if m:
            return int(m.group(1))
        # bare digits in string
        if s.isdigit():
            w=int(s)
            if 1<=w<=100:
                return w
    return None

best=None
for r in header_candidate_rows:
    week_cols={}
    for c in range(1, ws.max_column+1):
        w=parse_week(ws.cell(r,c).value)
        if w is not None:
            week_cols[w]=c
    if len(week_cols)>=10:
        # score by how many of 4..52 present
        score=sum(1 for w in range(4,53) if w in week_cols)
        if best is None or score>best[0]:
            best=(score,r,week_cols)

print('best header candidate:', best[:2] if best else None)
if best is None or best[0]<20:
    # fallback: assume weeks are in columns after label and contiguous; try to locate a '4' in nearby rows
    print('No strong header row found; showing a small window of rows for manual inspection...')
    for r in range(match_row-3, match_row+3):
        if r<1: continue
        vals=[]
        for c in range(1, min(ws.max_column,30)+1):
            v=ws.cell(r,c).value
            if isinstance(v,str):
                v=v.strip()
            vals.append(v)
        print(r, vals[:30])
    raise SystemExit('Need manual mapping')

score, header_row, week_cols = best
# Build demand list for weeks 4..52 using week_cols
missing=[w for w in range(4,53) if w not in week_cols]
print('header_row:', header_row, 'missing weeks:', missing[:10], 'count_missing', len(missing))
if missing:
    raise SystemExit('Missing week columns: '+str(missing))

demand=[]
for w in range(4,53):
    c=week_cols[w]
    v=ws.cell(match_row, c).value
    if v is None:
        v=0.0
    demand.append(float(v))

print('Extracted demand weeks 4..52 (49 values):')
print(demand)
print('Count:', len(demand), 'sum:', sum(demand))
