import openpyxl, re
path='/root/copy_of_capacity_sheet.xlsx'
wb=openpyxl.load_workbook(path, data_only=False)
ws=wb['Weld']

def norm(s):
    return re.sub(r'\s+',' ',str(s)).strip().lower()

target=norm('MIG weld Demand Total')
found=[]
for row in ws.iter_rows():
    for cell in row:
        v=cell.value
        if isinstance(v,str):
            if norm(v)==target:
                found.append((cell.coordinate, cell.row, cell.column, v))
            elif 'mig' in norm(v) and 'demand' in norm(v) and 'total' in norm(v):
                found.append((cell.coordinate, cell.row, cell.column, v))

print('Found matches (coordinate,row,col,value):')
