    print(item)
print('Total found:', len(found))

# Also, list some row first-non-empty values to understand layout
print('\nSample of first-non-empty cell values for first 80 rows:')
for r in range(1, 81):
    first=None
    for c in range(1, ws.max_column+1):
        v=ws.cell(r,c).value
        if v is None or (isinstance(v,str) and v.strip()==""):
            continue
        first=(c, v)
        break
    if first:
        c,v=first
        if isinstance(v,str):
            vs=norm(v)
        else:
            vs=str(v)
        if 'mig' in vs or 'demand' in vs or r<25:
            print(f'row {r} first_non_empty col {c} value {v!r}')
